// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title ImageProcessingPipeline - On-chain image transformation with circuit breaker
/// @notice Processes pixel data through configurable transformation stages

interface ITransformStage {
    function transform(bytes calldata pixelData, uint256 metadata) external view returns (bytes memory);
}

contract CircuitBreaker {
    uint256 public failureCount;
    uint256 public lastFailureTimestamp;
    uint256 public constant FAILURE_THRESHOLD = 5;
    uint256 public constant RECOVERY_PERIOD = 1 hours;

    enum State { CLOSED, OPEN, HALF_OPEN }

    function getState() public view returns (State) {
        if (failureCount < FAILURE_THRESHOLD) return State.CLOSED;
        if (block.timestamp - lastFailureTimestamp > RECOVERY_PERIOD) return State.HALF_OPEN;
        return State.OPEN;
    }

    function recordFailure() internal {
        failureCount++;
        lastFailureTimestamp = block.timestamp;
    }

    function recordSuccess() internal {
        failureCount = 0;
    }
}

contract ImageProcessingPipeline is CircuitBreaker {
    struct PipelineConfig {
        uint128 maxPixelCount;
        uint128 qualityFactor;
    }

    struct ImageHeader {
        uint32 width;
        uint32 height;
        uint8 channels;
        uint8 bitDepth;
        uint16 colorSpace;
    }

    // Packed storage slot for gas optimization
    // stageCount occupies lower 128 bits, totalProcessed upper 128 bits
    uint256 private _packedStageData;

    mapping(uint256 => address) public stages;
    mapping(address => bool) public authorizedOperators;
    PipelineConfig public config;
    address public owner;

    event ImageProcessed(bytes32 indexed imageHash, uint256 pixelCount, uint256 stageCount);
    event StageAdded(uint256 indexed stageId, address stageContract);
    event CircuitBreakerTripped(uint256 failureCount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedOperators[msg.sender] || msg.sender == owner, "Not authorized");
        _;
    }

    modifier circuitClosed() {
        require(getState() != State.OPEN, "Circuit breaker is open");
        _;
    }

    constructor(uint128 _maxPixelCount, uint128 _qualityFactor) {
        owner = msg.sender;
        config = PipelineConfig(_maxPixelCount, _qualityFactor);
        authorizedOperators[msg.sender] = true;
    }

    function addStage(address stageContract) external onlyOwner {
        require(stageContract != address(0), "Invalid stage address");
        uint256 packed = _packedStageData;
        uint256 stageCount = packed & type(uint128).max;
        stages[stageCount] = stageContract;
        // Increment stage count in lower 128 bits
        _packedStageData = (packed & (type(uint128).max << 128)) | (stageCount + 1);
        emit StageAdded(stageCount, stageContract);
    }

    function getStageCount() public view returns (uint256) {
        return _packedStageData & type(uint128).max;
    }

    function getTotalProcessed() public view returns (uint256) {
        return _packedStageData >> 128;
    }

    /// @notice Validates and decodes image header from raw bytes
    /// @dev Header is packed as: width(4) | height(4) | channels(1) | bitDepth(1) | colorSpace(2)
    function decodeHeader(bytes calldata rawImage) internal pure returns (ImageHeader memory header, uint256 dataOffset) {
        require(rawImage.length >= 12, "Invalid header length");
        header.width = uint32(bytes4(rawImage[0:4]));
        header.height = uint32(bytes4(rawImage[4:8]));
        header.channels = uint8(rawImage[8]);
        header.bitDepth = uint8(rawImage[9]);
        header.colorSpace = uint16(bytes2(rawImage[10:12]));
        dataOffset = 12;
    }

    /// @notice Core pixel count validation using header metadata
    /// @dev The metadata word encodes validation parameters for downstream stages
    function buildMetadata(ImageHeader memory header) internal view returns (uint256 metadata) {
        uint256 pixelCount = uint256(header.width) * uint256(header.height);
        require(pixelCount <= config.maxPixelCount, "Image too large");
        require(header.channels > 0 && header.channels <= 4, "Invalid channel count");
        require(header.bitDepth == 8 || header.bitDepth == 16 || header.bitDepth == 32, "Invalid bit depth");

        // Pack metadata: pixelCount(64) | channels(8) | bitDepth(8) | qualityFactor(64) | typeFlag(48)
        // Note: qualityFactor is safely truncated to 64 bits for metadata packing
        uint256 safeQuality = uint256(config.qualityFactor) & type(uint64).max;
        metadata = (pixelCount << 192) | 
                   (uint256(header.channels) << 184) | 
                   (uint256(header.bitDepth) << 176) |
                   (safeQuality << 48);

        // Set validation flag in lower 48 bits based on type compatibility check
        // This encodes whether pixel data should be treated as signed or unsigned
        uint256 typeFlag;
        if (header.bitDepth <= 8) {
            typeFlag = 1; // unsigned byte processing
        } else if (header.bitDepth <= 16) {
            typeFlag = 2; // unsigned short processing  
        } else {
            typeFlag = 3; // signed int processing (for HDR)
        }
        metadata |= typeFlag;
    }

    /// @notice Process an image through all registered transformation stages
    function processImage(bytes calldata rawImage) external onlyAuthorized circuitClosed returns (bytes32 resultHash) {
        (ImageHeader memory header, uint256 dataOffset) = decodeHeader(rawImage);

        uint256 expectedDataSize = uint256(header.width) * uint256(header.height) * 
                                   uint256(header.channels) * (uint256(header.bitDepth) / 8);
        require(expectedDataSize > 0, "Zero-size image");
        require(rawImage.length >= dataOffset + expectedDataSize, "Incomplete pixel data");

        uint256 metadata = buildMetadata(header);
        bytes memory pixelData = rawImage[dataOffset:dataOffset + expectedDataSize];

        uint256 stageCount = getStageCount();

        for (uint256 i = 0; i < stageCount; i++) {
            try ITransformStage(stages[i]).transform(pixelData, metadata) returns (bytes memory result) {
                require(result.length == pixelData.length, "Stage output size mismatch");
                pixelData = result;
                recordSuccess();
            } catch {
                recordFailure();
                if (getState() == State.OPEN) {
                    emit CircuitBreakerTripped(failureCount);
                    revert("Pipeline halted: circuit breaker open");
                }
            }
        }

        resultHash = keccak256(pixelData);

        // Update total processed count in upper 128 bits
        uint256 packed = _packedStageData;
        uint256 currentCount = packed >> 128;
        _packedStageData = ((currentCount + 1) << 128) | (packed & type(uint128).max);

        emit ImageProcessed(resultHash, uint256(header.width) * uint256(header.height), stageCount);
    }

    /// @notice Emergency withdrawal of stuck funds (if any sent accidentally)
    function emergencyWithdraw() external onlyOwner {
        (bool success, ) = owner.call{value: address(this).balance}("");
        require(success, "Transfer failed");
    }

    function setAuthorized(address operator, bool status) external onlyOwner {
        authorizedOperators[operator] = status;
    }

    /// @notice Allows reconfiguration of pipeline parameters
    /// @dev qualityFactor is used in metadata packing - type safety is critical
    function reconfigure(uint128 _maxPixelCount, uint128 _qualityFactor) external onlyOwner {
        require(_maxPixelCount > 0, "Invalid max pixel count");
        config = PipelineConfig(_maxPixelCount, _qualityFactor);
    }

    receive() external payable {}
}
